import re
from build_lib import q,w

def add(p,b,e,sol,codes,parts=(),extra=()):
 x=q(p);z=x['contenu'];g=lambda y,k:y.get(k,'').strip()
 s=f"# {p} {z['name']}\n\n## 中文题面\n\n### 题目描述\n\n{g(z,'description')}\n\n### 输入格式\n\n{g(z,'formatI')}\n\n### 输出格式\n\n{g(z,'formatO')}"
 for i,a in enumerate(x.get('samples',[]),1):s+=f"\n\n### 样例 {i}\n\n```text\n{a[0].rstrip()}\n```\n\n```text\n{a[1].rstrip()}\n```"
 s+=f"\n\n### 说明与限制\n\n{g(z,'hint')}\n\n## English Statement\n\n### Description\n\n{e[0]}\n\n### Input\n\n{e[1]}\n\n### Output\n\n{e[2]}\n\n### Constraints\n\n{e[3]}"
 w(b+'.md',s);w(b+' 题解.md',f'# {b} 题解\n\n{sol}')
 for k,v in codes.items():w(b+k,v)
 for i,v in enumerate(parts,1):w(f'{b} 部分分{i}.cpp',v)
 d='cph/'+b;k=0
 for k,a in enumerate(x.get('samples',[]),1):w(f'{d}/{b}_{k}.in',a[0]);w(f'{d}/{b}_{k}.ans',a[1])
 for a,o in extra:k+=1;w(f'{d}/{b}_{k}.in',a);w(f'{d}/{b}_{k}.ans',o)

A=r'''#include <bits/stdc++.h>
using namespace std;const int N=262144,P=998244353,G=3,M=64005,S=1500000;static int a[N],b[N],c[N],d[N],r[N],v[N],t[S],y[S],u[4*M],z[4*M],x[M],o[M];static int n,m,e,k;
int pw(int a,int b=P-2){int s=1;for(;b;b>>=1,a=1LL*a*a%P)if(b&1)s=1LL*s*a%P;return s;}
void f(int*a,int n,int q){for(int i=0;i<n;i++)if(i<r[i])swap(a[i],a[r[i]]);for(int l=2;l<=n;l<<=1){int w=pw(G,(P-1)/l);if(q<0)w=pw(w);for(int i=0;i<n;i+=l)for(int j=0,s=1;j<l/2;j++,s=1LL*s*w%P){int x=a[i+j],y=1LL*s*a[i+j+l/2]%P;a[i+j]=(x+y)%P;a[i+j+l/2]=(x-y+P)%P;}}if(q<0){int w=pw(n);for(int i=0;i<n;i++)a[i]=1LL*a[i]*w%P;}}
void ml(const int*x,int n,const int*y,int m,int*o){int l=n+m-1;if(1LL*n*m<=256){memset(o,0,l*sizeof(int));for(int i=0;i<n;i++)for(int j=0;j<m;j++)o[i+j]=(o[i+j]+1LL*x[i]*y[j])%P;return;}int q=1,s=0;while(q<l)q<<=1,s++;memset(a,0,q*sizeof(int));memset(b,0,q*sizeof(int));memcpy(a,x,n*sizeof(int));memcpy(b,y,m*sizeof(int));r[0]=0;for(int i=1;i<q;i++)r[i]=(r[i>>1]>>1)|((i&1)<<(s-1));f(a,q,1);f(b,q,1);for(int i=0;i<q;i++)a[i]=1LL*a[i]*b[i]%P;f(a,q,-1);memcpy(o,a,l*sizeof(int));}
void iv(const int*x,int n,int*y){memset(y,0,n*sizeof(int));y[0]=pw(x[0]);for(int k=1;k<n;k<<=1){int l=min(k<<1,n),q=1,s=0;while(q<l*2)q<<=1,s++;memset(a,0,q*sizeof(int));memset(b,0,q*sizeof(int));memcpy(a,x,l*sizeof(int));memcpy(b,y,k*sizeof(int));r[0]=0;for(int i=1;i<q;i++)r[i]=(r[i>>1]>>1)|((i&1)<<(s-1));f(a,q,1);f(b,q,1);for(int i=0;i<q;i++)b[i]=1LL*b[i]*(2-1LL*a[i]*b[i]%P+P)%P;f(b,q,-1);memcpy(y+k,b+k,(l-k)*sizeof(int));}}
void md(const int*x,int n,const int*g,int m,int*o){if(n<m){memcpy(o,x,n*sizeof(int));memset(o+n,0,(m-1-n)*sizeof(int));return;}if(m<=32){memcpy(c,x,n*sizeof(int));int w=pw(g[m-1]);for(int i=n-1;i>=m-1;i--){int s=1LL*c[i]*w%P;for(int j=0;j<m;j++)c[i-m+1+j]=(c[i-m+1+j]-1LL*s*g[j]%P+P)%P;}memcpy(o,c,(m-1)*sizeof(int));return;}int q=n-m+1;memset(c,0,q*sizeof(int));for(int i=0;i<m&&i<q;i++)c[i]=g[m-1-i];iv(c,q,d);for(int i=0;i<q;i++)v[i]=x[n-1-i];ml(v,q,d,q,c);for(int i=0;i<q;i++)v[i]=c[q-1-i];ml(g,m,v,q,c);for(int i=0;i<m-1;i++)o[i]=(x[i]-c[i]+P)%P;}
void bd(int q,int l,int h){if(l==h){u[q]=e;z[q]=2;t[e++]=(P-x[l])%P;t[e++]=1;return;}int m=(l+h)>>1;bd(q<<1,l,m);bd(q<<1|1,m+1,h);u[q]=e;z[q]=z[q<<1]+z[q<<1|1]-1;ml(t+u[q<<1],z[q<<1],t+u[q<<1|1],z[q<<1|1],t+e);e+=z[q];}
void ev(int q,int l,int h,const int*p,int n){if(l==h){o[l]=n?p[0]:0;return;}int m=(l+h)>>1,L=z[q<<1]-1,R=z[q<<1|1]-1,s=k;k+=L;md(p,n,t+u[q<<1],z[q<<1],y+s);int h0=k;k+=R;md(p,n,t+u[q<<1|1],z[q<<1|1],y+h0);ev(q<<1,l,m,y+s,L);ev(q<<1|1,m+1,h,y+h0,R);}
int main(){ios::sync_with_stdio(0);cin.tie(0);cin>>n>>m;for(int i=0;i<=n;i++)cin>>v[i];for(int i=0;i<m;i++)cin>>x[i];bd(1,0,m-1);k=0;if(n+1>=z[1]){k=m;md(v,n+1,t+u[1],z[1],y);ev(1,0,m-1,y,m);}else ev(1,0,m-1,v,n+1);for(int i=0;i<m;i++)cout<<o[i]<<'\n';}
'''
