def mdbuf(s):
 s=s.replace('r[N],v[N]','r[N],j[N],v[N]')
 a,b=s.split('void md',1);b,c=re.split(r'}\s*void bd',b,maxsplit=1)
 b=re.sub(r'\bv\b','j',b)
 return a+'void md'+b+'}\nvoid bd'+c
A=mdbuf(A);AS=mdbuf(AS)
add('P5050','P5050 【模板】多项式多点求值',('Given a polynomial $f(x)$ of degree $n$, compute $f(a_i)$ for every $i\\in[1,m]$.','The first line contains $n,m$. The second line contains the $n+1$ coefficients of $f$ in increasing order of degree. The third line contains the $m$ evaluation points $a_i$.','Print $m$ lines. Line $i$ contains $f(a_i)\\bmod 998244353$.','$1\\le n,m\\le64000$. Every coefficient and evaluation point is in $[0,998244353)$.') ,r'''Build the product tree whose leaf for point $a_i$ is $x-a_i$. Reduce $f$ modulo the polynomial at the root, then recursively reduce each remainder modulo the two child polynomials. At a leaf the constant remainder is exactly the requested value.

Polynomial multiplication and the reversed-polynomial division formula are implemented with NTT. The product tree has $O((n+m)\log m)$ stored coefficients. The total time is $O((n+m)\log^2(n+m))$ and the space usage is $O((n+m)\log m)$.''',{'.cpp':A,' 数据生成.cpp':AG,' 暴力.cpp':AB,' 对拍.cpp':AS},parts=[AB],extra=[('1 1\n0 0\n0\n','0\n'),('2 3\n1 2 3\n0 1 2\n','1\n6\n17\n'),('3 2\n998244352 1 0 1\n998244352 1\n','998244350\n1\n'),('1 3\n5 7\n3 3 0\n','26\n26\n5\n')])

